#!/bin/bash
###############################################################################
# Test: pop-up-book doc art stays valid, accessible and in sync (issue #251).
#
# The animated SVG scenes under docs/img/popup/ are generated by
# scripts/docs/popup_art.py. This guard checks that:
#   1. the committed SVGs match the generator exactly (--check);
#   2. every SVG is well-formed XML with <title>, <desc> and role="img";
#   3. none carries a <script>, an external href/url() or an event handler;
#   4. each honours prefers-reduced-motion and stays under the size budget;
#   5. every scene is embedded as a <picture> (dark <source> + light <img> with
#      alt text, same scene) somewhere, and every popup/ reference resolves;
#   6. every tracked human-facing doc is on DOC_TREE, the generated docs tree
#      (checked by --check in step 1; nested AGENTS.md, .github/ and .agents/
#      skills are exempt).
# Fully offline; needs only python3 (CI has it).
###############################################################################
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
PROJECT_ROOT="$(dirname "${SCRIPT_DIR}")"

if ! command -v python3 >/dev/null 2>&1; then
    echo "SKIP: python3 not found — doc-art check needs it (CI has python3)"
    exit 0
fi

cd "${PROJECT_ROOT}" || exit 1
fail=0

echo "== generator check"
python3 scripts/docs/popup_art.py --check || fail=1

echo "== SVG safety, accessibility and size"
python3 - <<'PY' || fail=1
import pathlib, re, sys, xml.dom.minidom
BUDGET = 40_000
bad = 0
files = sorted(pathlib.Path('docs/img/popup').glob('*.svg'))
if not files:
    print('FAIL: no SVGs in docs/img/popup'); sys.exit(1)
for f in files:
    text = f.read_text()
    errs = []
    try:
        doc = xml.dom.minidom.parseString(text)
    except Exception as e:
        errs.append(f'not well-formed XML: {e}')
        doc = None
    if doc is not None:
        root = doc.documentElement
        if root.getAttribute('role') != 'img': errs.append('root <svg> lacks role="img"')
        for tag in ('title', 'desc'):
            els = root.getElementsByTagName(tag)
            if not els or not (els[0].firstChild and els[0].firstChild.data.strip()):
                errs.append(f'missing or empty <{tag}>')
    if re.search(r'<script', text, re.I): errs.append('contains <script>')
    if re.search(r'\son[a-z]+\s*=', text, re.I): errs.append('contains an event-handler attribute')
    if re.search(r'(?:xlink:)?href\s*=\s*"(?!#)', text): errs.append('external href')
    if re.search(r'url\((?!#)', text): errs.append('external url()')
    if re.search(r'@import|@font-face', text): errs.append('imports a stylesheet or font')
    if 'prefers-reduced-motion' not in text: errs.append('no prefers-reduced-motion rule')
    if len(text.encode()) > BUDGET: errs.append(f'{len(text.encode())} bytes > {BUDGET} budget')
    for e in errs:
        print(f'FAIL: {f}: {e}'); bad += 1
print(f'checked {len(files)} SVGs' + ('' if bad else ' — all ok'))
sys.exit(1 if bad else 0)
PY

echo "== every scene is used as a light/dark <picture> pair, and every reference resolves"
python3 - <<'PY' || fail=1
import pathlib, re, subprocess, sys, os
scenes = {p.name.rsplit('-', 1)[0] for p in pathlib.Path('docs/img/popup').glob('*.svg')}
try:
    out = subprocess.run(['git', 'ls-files', '*.md'], capture_output=True, text=True, check=True).stdout.split()
except Exception:
    out = []
# Outside a git checkout (e.g. a release tarball) fall back to walking the tree.
mds = out or [str(p) for p in pathlib.Path('.').rglob('*.md') if '.git' not in p.parts and 'node_modules' not in p.parts]
paired, bad = set(), 0
PIC = re.compile(r'<picture>(.*?)</picture>', re.S)
for md in mds:
    text = pathlib.Path(md).read_text(errors='replace')
    for m in re.finditer(r'(?:src|srcset)="([^"]*popup/[a-z0-9-]+-(?:light|dark)\.svg)"', text):
        path = os.path.normpath(os.path.join(os.path.dirname(md), m.group(1)))
        if not os.path.isfile(path):
            print(f'FAIL: {md}: {m.group(1)} does not exist'); bad += 1
    for block in PIC.findall(text):
        dark = re.search(r'<source media="\(prefers-color-scheme: dark\)" srcset="[^"]*popup/([a-z0-9-]+)-dark\.svg"', block)
        light = re.search(r'<img src="[^"]*popup/([a-z0-9-]+)-light\.svg"[^>]*\balt="([^"]+)"', block)
        if not (dark or light):
            continue
        if not (dark and light and dark.group(1) == light.group(1)):
            print(f'FAIL: {md}: a popup <picture> needs a dark <source> and a light <img alt="..."> of the same scene'); bad += 1
            continue
        paired.add(dark.group(1))
for s in sorted(scenes - paired):
    print(f'FAIL: scene {s} is not used as a light+dark <picture> pair in any doc'); bad += 1
print(f'{len(scenes)} scenes, {len(paired)} used as pairs across {len(mds)} docs' + ('' if bad else ' — all ok'))
sys.exit(1 if bad else 0)
PY

if [ "$fail" -ne 0 ]; then
    echo "FAIL: doc art"
    exit 1
fi
echo "PASS: doc art"
